package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.assetexport.*;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import org.junit.jupiter.api.Test;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class AssetExportCommandCodecTest {
    final UUID tenant=UUID.fromString("58000000-0000-4000-8000-000000000001"),actor=UUID.fromString("58000000-0000-4000-8000-000000000002");
    Command command(){return new Command(new Access(tenant,actor,7,"msp",true),new Filters("router","unknown","site-a","中文 %_| 原文"));}
    List<String> fields(){return new ArrayList<>(Arrays.asList("mop-asset-export-command-v1",tenant.toString(),actor.toString(),"7","msp","router","unknown","site-a","中文 %_| 原文"));}
    byte[] raw(List<String> fields)throws IOException{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);for(String value:fields){if(value==null)out.writeInt(-1);else{byte[] v=value.getBytes(StandardCharsets.UTF_8);out.writeInt(v.length);out.write(v);}}return bytes.toByteArray();}
    @Test void goldenFingerprintRemainsByteCompatibleWithPreviouslyPublishedStateModel(){assertEquals("a4f83b0e0987b9b31e2abd03f87af8948944606ab640209e88e2c05c19dc5b05",command().fingerprint());}
    @Test void explicitFramingMatchesIndependentEncoderAndRoundTrips()throws Exception{byte[] encoded=command().canonicalBytes();assertArrayEquals(raw(fields()),encoded);assertEquals(command(),AssetExportCommandCodec.decode(encoded));}
    @Test void nullableFiltersAndEmptyStringsRemainDistinct(){for(String value:Arrays.asList(null,""," ","%_|=literal", "😀e\u0301")){var c=new Command(command().acceptedAccess(),new Filters(null,null,null,value));assertEquals(c,AssetExportCommandCodec.decode(c.canonicalBytes()));}var a=new Command(command().acceptedAccess(),new Filters(null,null,null,null));var b=new Command(command().acceptedAccess(),new Filters(null,null,null,""));assertNotEquals(a.fingerprint(),b.fingerprint());}
    @Test void outputArraysAndDecodedInputsDoNotAliasCommandState(){var command=command();byte[] encoded=command.canonicalBytes();var decoded=AssetExportCommandCodec.decode(encoded);encoded[0]=99;assertEquals(command,decoded);assertEquals(command,AssetExportCommandCodec.decode(command.canonicalBytes()));}
    @Test void missingNullEmptyAndOversizeInputsFailWithoutFields(){assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(null));assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(new byte[0]));assertEquals(413,assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(new byte[4097])).status);assertThrows(DomainException.class,()->AssetExportCommandCodec.encode(null));}
    @Test void everyTruncatedPrefixFailsClosed(){byte[] valid=command().canonicalBytes();for(int length=0;length<valid.length;length++){final byte[] truncated=Arrays.copyOf(valid,length);assertEquals(400,assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(truncated)).status);}}
    @Test void trailingBytesAndExtraFieldsCannotBeSilentlyIgnored()throws Exception{var fields=fields();fields.add("extra");assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));byte[] valid=command().canonicalBytes();assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(Arrays.copyOf(valid,valid.length+1)));}
    @Test void unsupportedMagicOrVersionIsRejected()throws Exception{for(String magic:Arrays.asList(null,"","mop-asset-export-command-v2","other")){var fields=fields();fields.set(0,magic);assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));}}
    @Test void alternativeUuidSpellingsAreNotNormalizedIntoAnEquivalentCommand()throws Exception{for(String value:List.of("58000000-0000-4000-8000-00000000000A","1-1-1-1-1","not-uuid")){var fields=fields();fields.set(1,value);assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));}}
    @Test void permissionVersionHasOneCanonicalPositiveSafeIntegerRepresentation()throws Exception{for(String value:Arrays.asList(null,"","+7","07","0","-1","7.0","9007199254740992")){var fields=fields();fields.set(3,value);assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));}var max=new Command(new Access(tenant,actor,9007199254740991L,"padmin",true),new Filters(null,null,null,null));assertEquals(max,AssetExportCommandCodec.decode(max.canonicalBytes()));}
    @Test void nullRequiredFieldsAndUnsupportedRolesReject()throws Exception{for(int index:new int[]{1,2,4}){var fields=fields();fields.set(index,null);assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));}for(String role:List.of("viewer","tadmin","ADMIN")){var fields=fields();fields.set(4,role);assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));}}
    @Test void maliciousLengthPrefixesRejectBeforeAllocatingTheirDeclaredSize(){for(int length:new int[]{-2,513,Integer.MAX_VALUE,Integer.MIN_VALUE}){byte[] value={(byte)(length>>>24),(byte)(length>>>16),(byte)(length>>>8),(byte)length};assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(value));}}
    @Test void malformedUtf8IsNotReplacedByUnicodeSubstitution()throws Exception{byte[] valid=raw(fields());valid[4]=(byte)0xff;assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(valid));var fields=fields();fields.set(8,"X");byte[] end=raw(fields());end[end.length-1]=(byte)0xc0;assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(end));}
    @Test void decodedFiltersStillUseThePublicLedgerConstraints()throws Exception{for(var change:List.of(new String[]{"5","invented"},new String[]{"6","invented"},new String[]{"7","s".repeat(65)},new String[]{"8","q".repeat(101)},new String[]{"8","a\u0000b"})){var fields=fields();fields.set(Integer.parseInt(change[0]),change[1]);assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));}}
    @Test void errorDoesNotExposeRawSensitiveLookingInput()throws Exception{var fields=fields();fields.set(4,"SYNTHETIC_SECRET");var error=assertThrows(DomainException.class,()->AssetExportCommandCodec.decode(raw(fields)));assertEquals("EXPORT_COMMAND_INVALID",error.code);assertFalse(error.getMessage().contains("SYNTHETIC"));}
    @Test void validReencodedForeignIdentityStillDoesNotAuthorizeAnExistingJob()throws Exception{var altered=fields();altered.set(1,UUID.randomUUID().toString());var decoded=AssetExportCommandCodec.decode(raw(altered));assertNotEquals(command().fingerprint(),decoded.fingerprint());var job=AssetExportJobState.queued(UUID.randomUUID(),command(),Instant.EPOCH);assertEquals(404,assertThrows(DomainException.class,()->job.authorize(decoded.acceptedAccess())).status);}
    @Test void seededRandomBytesEitherRejectSafelyOrHaveAnExactCanonicalRoundTrip(){var random=new Random(20261004);for(int i=0;i<500;i++){byte[] bytes=new byte[random.nextInt(600)+1];random.nextBytes(bytes);try{var result=AssetExportCommandCodec.decode(bytes);assertArrayEquals(bytes,result.canonicalBytes());}catch(DomainException expected){assertEquals(400,expected.status);assertEquals("EXPORT_COMMAND_INVALID",expected.code);}}}
    @Test void boundDecodeRequiresExactRetainedAcceptanceAndFingerprint(){var c=command();assertEquals(c,AssetExportCommandCodec.decodeBound(c.canonicalBytes(),c.acceptedAccess(),c.fingerprint()));}
    @Test void boundForeignIdentityRemainsNotFound(){var c=command();for(var a:List.of(new Access(UUID.randomUUID(),actor,7,"msp",true),new Access(tenant,UUID.randomUUID(),7,"msp",true))){assertEquals(404,assertThrows(DomainException.class,()->AssetExportCommandCodec.decodeBound(c.canonicalBytes(),a,c.fingerprint())).status);}}
    @Test void retainedRoleVersionOrActiveMismatchCannotAuthorizeDecodedScope(){var c=command();for(var a:List.of(new Access(tenant,actor,8,"msp",true),new Access(tenant,actor,7,"padmin",true),new Access(tenant,actor,7,"msp",false))){assertEquals(409,assertThrows(DomainException.class,()->AssetExportCommandCodec.decodeBound(c.canonicalBytes(),a,c.fingerprint())).status);}}
    @Test void boundDigestRejectsMalformedOrMismatchedFacts(){var c=command();for(String h:Arrays.asList(null,"","A".repeat(64),"0".repeat(63),"secret")){assertEquals(400,assertThrows(DomainException.class,()->AssetExportCommandCodec.decodeBound(c.canonicalBytes(),c.acceptedAccess(),h)).status);}assertEquals(409,assertThrows(DomainException.class,()->AssetExportCommandCodec.decodeBound(c.canonicalBytes(),c.acceptedAccess(),"0".repeat(64))).status);assertEquals(400,assertThrows(DomainException.class,()->AssetExportCommandCodec.decodeBound(c.canonicalBytes(),null,c.fingerprint())).status);}

}
